"""Render credit and notice projections from the existing dependency inventory."""
from pathlib import Path
import argparse,hashlib,json
ROOT=Path(__file__).resolve().parents[1]
parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
inventory=json.loads((ROOT/'docs/dependency-inventory.json').read_text(encoding='utf-8'))
product=inventory['product'];priority={'viewer source':0,'Gizmo3D runtime editor-gizmo port':1,'Godot Engine':2,'Vulkan Radix Sort (historical upstream credit)':3}
components=sorted(inventory['components'],key=lambda row:priority.get(row['component'],4))
credits=['# PXRFusion credits','','<!-- Generated by tools/generate_credits.py from docs/dependency-inventory.json. -->','',product['foundation_statement'],'',product['copyright_scope'],'','Project code is MIT licensed. Third-party code, models, fonts and other assets retain their respective terms. Notices do not resolve missing ownership or redistribution evidence.','','| Component | Authors / role | Source | Licence / provenance |','|---|---|---|---|']
def cell(value):return str(value).replace('|',r'\|').replace('\n',' ')
manifest=[]
for row in components:
    authors=', '.join(row.get('authors',[]));role=row.get('role','')
    details=' · '.join(part for part in (authors,role) if part) or 'See retained notices'
    link='[upstream]('+row['upstream']+')' if row.get('upstream') else 'Source/revision evidence incomplete'
    status=row.get('license','See component terms')+' · '+row.get('status','')
    name='GodotGaussianSplatting' if row['component']=='viewer source' else row['component']
    credits.append('| '+' | '.join(map(cell,[name,details,link,status]))+' |')
    manifest.append({'name':name,'authors':authors,'role':role,'upstream':row.get('upstream',''),'license':row.get('license','See component terms'),'status':row.get('status','')})
credits+=['','The original research and historical demo credits remain in [the upstream README archive](docs/archive/upstream-README.md). Current application performance claims are limited to the recorded qualification evidence.','','Full retained text: [THIRD_PARTY_NOTICES.txt](THIRD_PARTY_NOTICES.txt). Machine-readable ownership/provenance: [dependency inventory](docs/dependency-inventory.json). Exact historical GS import revision remains unknown.','','The running application also exposes notices from its actual Godot binary in Workspace settings → About & licences.']
notices=['PXRFusion — project licence and retained third-party notices','Generated from docs/dependency-inventory.json by tools/generate_credits.py.','Project code licence: MIT. Third-party terms remain independent.','This collection preserves available notices; unresolved provenance is recorded in CREDITS.md.','','=== PROJECT LICENCE: retained original work and company contributions ===',(ROOT/'LICENSE').read_text(encoding='utf-8'),'']
hashes={};retained={}
for name in inventory['notice_files']:
    path=ROOT/name
    if not path.is_file():raise SystemExit('Missing registered notice: '+name)
    raw=path.read_bytes()
    try:decoded=raw.decode('utf-16') if raw[:2] in (b'\xff\xfe',b'\xfe\xff') else raw.decode('utf-8-sig')
    except UnicodeDecodeError:decoded=raw.decode('cp1252')
    decoded=decoded.replace('\r\n','\n').replace('\r','\n')
    hashes[name]=hashlib.sha256(decoded.encode('utf-8')).hexdigest()
    body=('Identical notice text retained above under: '+retained[hashes[name]]) if hashes[name] in retained else decoded
    retained.setdefault(hashes[name],name)
    notices+=['='*78,name,'Notice text SHA-256 (UTF-8/LF): '+hashes[name],'='*78,body,'']
notice_text='\n'.join(notices)+'\n'
payload={'schema_version':1,'product':product,'components':manifest,'notice_sha256':hashlib.sha256(notice_text.encode('utf-8')).hexdigest(),'source_notice_text_sha256':hashes,'notice_hash_encoding':'UTF-8 with LF line endings; original notice files retained separately.'}
outputs={'CREDITS.md':'\n'.join(credits)+'\n','THIRD_PARTY_NOTICES.txt':notice_text,'assets/legal/notices.txt':notice_text,'assets/legal/credits.json':json.dumps(payload,indent=2,ensure_ascii=False)+'\n'}
for name,text in outputs.items():
    path=ROOT/name
    if args.check:
        if not path.is_file() or path.read_text(encoding='utf-8')!=text:raise SystemExit('Stale credits projection: '+name)
    else:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text,encoding='utf-8',newline='\n')
print('Credits/notices projections current:',len(components),'components,',len(hashes),'retained notice files')
